/**
 * The optional dashboards profile (14 §8): Prometheus scrapes the app's /api/v1/metrics over the compose network with a
 * bearer token, Grafana reads Prometheus. Both listen on 127.0.0.1 only (reach them through an SSH tunnel) and run as the
 * host user, so the token file can stay mode 0600. Generated by `tincan init`; start with
 * `docker compose --profile dashboards up -d`.
 */

export const PROMETHEUS_IMAGE = "prom/prometheus:v3.5.0";
export const GRAFANA_IMAGE = "grafana/grafana:12.1.0";

export function prometheusConfig(): string {
  return `# Generated by \`tincan init\` (14 §8).
global:
  scrape_interval: 15s
  evaluation_interval: 30s
rule_files:
  - /etc/prometheus/alerts.yml
scrape_configs:
  - job_name: tincan
    metrics_path: /api/v1/metrics
    authorization:
      type: Bearer
      credentials_file: /etc/prometheus/metrics-token
    static_configs:
      - targets: ["tincan:3000"]
  # LiveKit's own metrics (CPU, bandwidth, packet loss, rooms) are off by default. To use them add
  # \`prometheus_port: 6789\` to livekit.yaml, keep 6789 closed in the host firewall (host networking publishes it on
  # every interface), restart LiveKit and uncomment:
  # - job_name: livekit
  #   static_configs:
  #     - targets: ["host.docker.internal:6789"]
`;
}

export function alertRules(): string {
  return `# Alerts worth having (14 §8). Prometheus shows them under Alerts; wire an Alertmanager if you want mail or chat.
groups:
  - name: tincan
    rules:
      - alert: TinCanDown
        expr: up{job="tincan"} == 0
        for: 2m
        labels: { severity: critical }
        annotations: { summary: "The Tin Can app has not answered a scrape for 2 minutes" }
      - alert: VoiceRepairsKeepHappening
        # A primary path (webhooks, the fast enforcement) is broken when repairs go on and on (18 T34).
        expr: sum(rate(tincan_reconcile_repairs_total{kind!="orphan_room"}[15m])) > 0.002
        for: 30m
        labels: { severity: warning }
        annotations: { summary: "The voice reconciler keeps repairing state; check the LiveKit webhook URL" }
      - alert: LiveKitUnreachable
        expr: tincan_livekit_reachable == 0
        for: 5m
        labels: { severity: critical }
        annotations: { summary: "The app cannot reach LiveKit's API" }
      - alert: ServerErrors
        expr: sum(rate(tincan_http_requests_total{status=~"5.."}[5m])) / sum(rate(tincan_http_requests_total[5m])) > 0.05
        for: 10m
        labels: { severity: warning }
        annotations: { summary: "More than 5 % of requests end in a 5xx error" }
      - alert: EventLoopBlocked
        expr: nodejs_eventloop_lag_p99_seconds > 0.25
        for: 10m
        labels: { severity: warning }
        annotations: { summary: "The server's event loop is blocked for a quarter of a second at the 99th percentile" }
      - alert: OutboxBacklog
        expr: tincan_outbox_backlog > 1000
        for: 10m
        labels: { severity: warning }
        annotations: { summary: "Search indexing and other outbox work is falling behind" }
      - alert: UploadMemoryHigh
        expr: tincan_uploads_in_flight_bytes > 1073741824
        for: 1m
        labels: { severity: warning }
        annotations: { summary: "Uploads hold more than 1 GiB in memory; lower the file size limit or add memory (18 §N)" }
      - alert: BackupStale
        # Needs 'tincan backup' on a schedule (14 §6). A Host who makes no backups sees this one always, on purpose.
        expr: time() - tincan_last_backup_timestamp_seconds > 172800
        for: 1h
        labels: { severity: warning }
        annotations: { summary: "No successful backup for 48 hours (or ever)" }
      - alert: BackupFailed
        expr: tincan_last_backup_failed == 1
        for: 5m
        labels: { severity: warning }
        annotations: { summary: "The newest backup run failed; look at the backup log and run tincan doctor" }
      - alert: MemoryHigh
        expr: process_resident_memory_bytes > 1.5e9
        for: 15m
        labels: { severity: warning }
        annotations: { summary: "The app uses more than 1.5 GB of memory" }
`;
}

export function grafanaDatasource(): string {
  return `apiVersion: 1
datasources:
  - name: Prometheus
    uid: tincan-prometheus
    type: prometheus
    access: proxy
    url: http://prometheus:9090
    isDefault: true
`;
}

export function grafanaProvider(): string {
  return `apiVersion: 1
providers:
  - name: tincan
    type: file
    disableDeletion: true
    options:
      path: /var/lib/grafana-dashboards
`;
}

interface Panel {
  title: string;
  unit?: string;
  exprs: { expr: string; legend?: string }[];
}

const ROWS: Panel[][] = [
  [
    {
      title: "Requests per second",
      unit: "reqps",
      exprs: [{ expr: "sum by (status) (rate(tincan_http_requests_total[5m]))", legend: "{{status}}" }],
    },
    {
      title: "Request time, 95th percentile",
      unit: "s",
      exprs: [
        {
          expr: "histogram_quantile(0.95, sum by (le) (rate(tincan_http_request_duration_seconds_bucket[5m])))",
          legend: "p95",
        },
      ],
    },
    {
      title: "Gateway sessions and users online",
      exprs: [
        { expr: "tincan_gateway_sessions", legend: "sessions" },
        { expr: "tincan_gateway_users_online", legend: "online" },
      ],
    },
  ],
  [
    {
      title: "People in voice, rooms",
      exprs: [
        { expr: "tincan_voice_participants", legend: "people" },
        { expr: "tincan_voice_rooms", legend: "rooms" },
      ],
    },
    {
      title: "Voice reconciler repairs per minute (should stay at zero)",
      exprs: [{ expr: "sum by (kind) (rate(tincan_reconcile_repairs_total[10m])) * 60", legend: "{{kind}}" }],
    },
    {
      title: "LiveKit reachable, webhook lag",
      exprs: [
        { expr: "tincan_livekit_reachable", legend: "reachable" },
        { expr: "tincan_voice_webhook_lag_seconds", legend: "lag s" },
      ],
    },
  ],
  [
    {
      title: "Memory",
      unit: "bytes",
      exprs: [
        { expr: "process_resident_memory_bytes", legend: "resident" },
        { expr: "process_array_buffers_bytes", legend: "buffers" },
        { expr: "tincan_uploads_in_flight_bytes", legend: "uploads in flight" },
      ],
    },
    {
      title: "Event loop delay, 99th percentile",
      unit: "s",
      exprs: [
        { expr: "nodejs_eventloop_lag_p99_seconds", legend: "p99" },
        { expr: "nodejs_eventloop_lag_max_seconds", legend: "max" },
      ],
    },
    {
      title: "Database ping, outbox backlog",
      exprs: [
        { expr: "tincan_db_ping_seconds", legend: "db ping s" },
        { expr: "tincan_outbox_backlog", legend: "outbox" },
      ],
    },
  ],
  [
    {
      title: "Uploads per minute, refused per minute",
      exprs: [
        { expr: "rate(tincan_uploads_total[5m]) * 60", legend: "accepted" },
        { expr: "rate(tincan_uploads_rejected_total[5m]) * 60", legend: "refused" },
      ],
    },
    {
      title: "Moderation actions per hour",
      exprs: [{ expr: "sum by (action) (increase(tincan_audit_events_total[1h]))", legend: "{{action}}" }],
    },
    {
      title: "Job failures, E2EE key rotations",
      exprs: [
        { expr: "sum by (job) (increase(tincan_job_failures_total[1h]))", legend: "{{job}} failed" },
        { expr: "increase(tincan_voice_e2ee_rotations_total[1h])", legend: "key rotations" },
      ],
    },
  ],
];

/** One dashboard, generated from a list so the JSON stays consistent and reviewable. */
export function grafanaDashboard(): string {
  let id = 0;
  const panels = ROWS.flatMap((row, r) =>
    row.map((p, c) => ({
      id: ++id,
      type: "timeseries",
      title: p.title,
      datasource: { type: "prometheus", uid: "tincan-prometheus" },
      gridPos: { h: 8, w: 24 / row.length, x: c * (24 / row.length), y: r * 8 },
      fieldConfig: { defaults: { ...(p.unit ? { unit: p.unit } : {}) }, overrides: [] },
      targets: p.exprs.map((e, i) => ({
        refId: String.fromCharCode(65 + i),
        expr: e.expr,
        legendFormat: e.legend ?? "",
      })),
    })),
  );
  return (
    JSON.stringify(
      {
        uid: "tincan-overview",
        title: "Tin Can",
        tags: ["tincan"],
        timezone: "browser",
        schemaVersion: 39,
        refresh: "30s",
        time: { from: "now-6h", to: "now" },
        panels,
      },
      null,
      2,
    ) + "\n"
  );
}

export const COMPOSE_SERVICES = `  # Dashboards. Start them with: docker compose --profile dashboards up -d
  # Both listen on 127.0.0.1 only: \`ssh -L 3001:127.0.0.1:3001 you@server\`, then open http://localhost:3001.
  prometheus:
    profiles: [dashboards]
    image: ${PROMETHEUS_IMAGE}
    restart: unless-stopped
    user: "\${HOST_UID:-1000}:\${HOST_GID:-1000}"
    command:
      - --config.file=/etc/prometheus/prometheus.yml
      - --storage.tsdb.path=/prometheus
      - --storage.tsdb.retention.time=30d
    volumes:
      - ./monitoring/prometheus.yml:/etc/prometheus/prometheus.yml:ro
      - ./monitoring/alerts.yml:/etc/prometheus/alerts.yml:ro
      - ./monitoring/metrics-token:/etc/prometheus/metrics-token:ro
      - ./monitoring/prometheus-data:/prometheus
    extra_hosts:
      - "host.docker.internal:host-gateway"
    ports:
      - "127.0.0.1:9090:9090"
    read_only: true
    cap_drop: [ALL]
    security_opt: ["no-new-privileges:true"]

  grafana:
    profiles: [dashboards]
    image: ${GRAFANA_IMAGE}
    restart: unless-stopped
    user: "\${HOST_UID:-1000}:\${HOST_GID:-1000}"
    depends_on: [prometheus]
    environment:
      GF_SECURITY_ADMIN_PASSWORD: \${GRAFANA_PASSWORD}
      GF_USERS_ALLOW_SIGN_UP: "false"
      GF_ANALYTICS_REPORTING_ENABLED: "false"
      GF_ANALYTICS_CHECK_FOR_UPDATES: "false"
      GF_ANALYTICS_CHECK_FOR_PLUGIN_UPDATES: "false"
      GF_SERVER_ROOT_URL: http://localhost:3001
    volumes:
      - ./monitoring/grafana/provisioning:/etc/grafana/provisioning:ro
      - ./monitoring/grafana/dashboards:/var/lib/grafana-dashboards:ro
      - ./monitoring/grafana-data:/var/lib/grafana
    ports:
      - "127.0.0.1:3001:3000"
    cap_drop: [ALL]
    security_opt: ["no-new-privileges:true"]
`;
